#include <bits/stdc++.h>
using namespace std;

struct Event {
    double t;
    double delta;
    bool operator<(const Event& other) const {
        if (fabs(t - other.t) > 1e-12) return t < other.t;
        return delta < other.delta;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double L;

    while (cin >> n >> L) {
        if (n == 0 && fabs(L) < 1e-12) break;

        vector<Event> events;
        for (int i = 0; i < n; ++i) {
            double s, e, w;
            cin >> s >> e >> w;
            events.push_back({s, +w});
            events.push_back({e, -w});
        }

        sort(events.begin(), events.end());

        vector<pair<double,double>> segs; // {duration, consumption rate}
        double curRate = 0.0;
        double prevT = events[0].t;

        int i = 0;
        while (i < (int)events.size()) {
            double t = events[i].t;

            if (t > prevT) {
                segs.push_back({t - prevT, curRate});
                prevT = t;
            }

            while (i < (int)events.size() && fabs(events[i].t - t) < 1e-12) {
                curRate += events[i].delta;
                ++i;
            }
        }

        auto feasible = [&](double p) -> bool {
            double water = L; // assume tank starts full
            for (auto &seg : segs) {
                double dt = seg.first;
                double need = seg.second;
                water += (p - need) * dt;
                if (water < -1e-9) return false;
                if (water > L) water = L;
            }
            return true;
        };

        double lo = 0.0, hi = 0.0;
        for (auto &seg : segs) hi = max(hi, seg.second);
        hi = max(hi, 1.0);

        while (!feasible(hi)) hi *= 2.0;

        for (int it = 0; it < 100; ++it) {
            double mid = (lo + hi) / 2.0;
            if (feasible(mid)) hi = mid;
            else lo = mid;
        }

        cout << fixed << setprecision(3) << hi << "\n";
    }

    return 0;
}

