int main() {
    int L;
    while (scanf("%d", &L) == 1 && L != 0) {
        int n;
        scanf("%d", &n);
        int s[100], e[100];
        double u[100];
        for (int i = 0; i < n; i++) {
            scanf("%d %d %lf", &s[i], &e[i], &u[i]);
        }

        // Collect all breakpoints
        double times[200];
        int nt = 0;
        for (int i = 0; i < n; i++) {
            times[nt++] = s[i];
            times[nt++] = e[i];
        }

        double min_r = 0.0;

        for (int k = 0; k < nt; k++) {
            double t = times[k];
            if (t <= 0) continue;
            // Compute used(t)
            double used = 0.0;
            for (int i = 0; i < n; i++) {
                double a = s[i], b = e[i];
                if (t > a) {
                    double end = t < b ? t : b;
                    used += u[i] * (end - a);
                }
            }
            double needed = (used - L) / t;
            if (needed > min_r) min_r = needed;
        }

        printf("%.2f\n", min_r);
    }
    return 0;
}

