typedef struct {
    double s, e, v;
} Seg;

int cmp_seg(const void *a, const void *b) {
    const Seg *x = (const Seg *)a;
    const Seg *y = (const Seg *)b;
    if (x->s < y->s) return -1;
    if (x->s > y->s) return 1;
    if (x->e < y->e) return -1;
    if (x->e > y->e) return 1;
    return 0;
}

int main(void) {
    int n;
    double L;

    while (scanf("%d %lf", &n, &L) == 2) {
        if (n == 0 && L == 0) break;

        Seg *a = (Seg *)malloc(sizeof(Seg) * n);
        double *times = (double *)malloc(sizeof(double) * (2 * n + 2));
        int m = 0;

        for (int i = 0; i < n; i++) {
            scanf("%lf %lf %lf", &a[i].s, &a[i].e, &a[i].v);
            times[m++] = a[i].s;
            times[m++] = a[i].e;
        }

        qsort(a, n, sizeof(Seg), cmp_seg);

        /* sort and unique times */
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                if (times[j] < times[i]) {
                    double tmp = times[i];
                    times[i] = times[j];
                    times[j] = tmp;
                }
            }
        }

        int k = 0;
        for (int i = 0; i < m; i++) {
            if (i == 0 || times[i] != times[i - 1]) {
                times[k++] = times[i];
            }
        }

        double ans = 0.0;

        /* For every possible ending time t, compute:
           required pump rate >= max over intervals [u, t]:
           (consumption(u,t) - L) / (t-u)
           This guarantees tank never becomes empty if initially full. */
        for (int ti = 1; ti < k; ti++) {
            double t = times[ti];
            double cons = 0.0;

            for (int ui = ti - 1; ui >= 0; ui--) {
                double l = times[ui];
                double r = times[ui + 1];
                double rate = 0.0;

                for (int i = 0; i < n; i++) {
                    if (a[i].s <= l && a[i].e >= r) {
                        rate += a[i].v;
                    }
                }

                cons += rate * (r - l);
                double len = t - l;
                double need = (cons - L) / len;
                if (need > ans) ans = need;
            }
        }

        if (ans < 0) ans = 0;

        printf("%.3f\n", ans + 1e-9);

        free(a);
        free(times);
    }

    return 0;
}

