public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            int n = sc.nextInt(); // number of usages
            if (n == 0) break;
            double L = sc.nextDouble(); // capacity

            double[] start = new double[n];
            double[] end = new double[n];
            double[] rate = new double[n];

            for (int i = 0; i < n; i++) {
                start[i] = sc.nextDouble();
                end[i] = sc.nextDouble();
                rate[i] = sc.nextDouble();
            }

            double low = 0, high = 1e9;
            for (int iter = 0; iter < 200; iter++) {
                double mid = (low + high) / 2;
                if (feasible(mid, L, start, end, rate)) {
                    high = mid;
                } else {
                    low = mid;
                }
            }
            System.out.printf("%.3f\n", high);
        }
        sc.close();
    }

    static boolean feasible(double pumpRate, double capacity, 
                            double[] start, double[] end, double[] rate) {
        List<double[]> events = new ArrayList<>();
        int n = start.length;
        for (int i = 0; i < n; i++) {
            events.add(new double[]{start[i], rate[i]});
            events.add(new double[]{end[i], -rate[i]});
        }
        events.sort((a, b) -> Double.compare(a[0], b[0]));

        double current = capacity; // start full
        double lastTime = 0;
        double netRate = 0;

        for (double[] e : events) {
            double time = e[0];
            double delta = e[1];

            double elapsed = time - lastTime;
            double change = (netRate - pumpRate) * elapsed;
            current += change;
            if (current < 0) return false;
            if (current > capacity) current = capacity;

            netRate += delta;
            lastTime = time;
        }
        return true;
    }
}

