public class Main {
    static int n;
    static int[][] intervals; // start, end, rate

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int L = sc.nextInt();
            if (!sc.hasNextInt()) break;
            n = sc.nextInt();
            if (n == 0 && L == 0) break;
            intervals = new int[n][3];
            for (int i = 0; i < n; i++) {
                intervals[i][0] = sc.nextInt();
                intervals[i][1] = sc.nextInt();
                intervals[i][2] = sc.nextInt();
            }
            double lo = 0, hi = 1e9;
            for (int iter = 0; iter < 200; iter++) {
                double mid = (lo + hi) / 2;
                if (feasible(mid, L)) hi = mid;
                else lo = mid;
            }
            System.out.printf("%.2f%n", hi);
        }
    }

    static boolean feasible(double p, double L) {
        List<int[]> events = new ArrayList<>();
        for (int[] iv : intervals) {
            events.add(new int[]{iv[0], iv[2]});
            events.add(new int[]{iv[1], -iv[2]});
        }
        events.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        double tank = L;
        double currentRate = 0;
        int prevTime = 0;
        for (int[] ev : events) {
            int t = ev[0];
            double dt = t - prevTime;
            double netRate = p - currentRate;
            if (currentRate > 0) {
                // check tank doesn't go empty
                if (netRate < 0) {
                    double emptyTime = tank / (-netRate);
                    if (emptyTime < dt) return false;
                }
                tank += netRate * dt;
            } else {
                tank = Math.min(L, tank + p * dt);
            }
            currentRate += ev[1];
            prevTime = t;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Event implements Comparable<Event> {
        int time;
        double delta;

        Event(int time, double delta) {
            this.time = time;
            this.delta = delta;
        }

        public int compareTo(Event o) {
            return Integer.compare(this.time, o.time);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == Integer.MIN_VALUE) break;
            int L = fs.nextInt();

            if (n == 0 && L == 0) break;

            List<Event> events = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                int s = fs.nextInt();
                int t = fs.nextInt();
                int u = fs.nextInt();
                events.add(new Event(s, u));
                events.add(new Event(t, -u));
            }

            Collections.sort(events);

            double low = 0.0, high = 1000000.0;
            for (int it = 0; it < 100; it++) {
                double mid = (low + high) / 2.0;
                if (can(mid, L, events)) {
                    high = mid;
                } else {
                    low = mid;
                }
            }

            out.append(String.format(Locale.US, "%.10f%n", high));
        }

        System.out.print(out.toString());
    }

    static boolean can(double pump, int L, List<Event> events) {
        double water = L;
        double usage = 0.0;
        int idx = 0;
        int prevTime = events.get(0).time;

        while (idx < events.size()) {
            int curTime = events.get(idx).time;
            int dt = curTime - prevTime;

            if (dt > 0) {
                water += (pump - usage) * dt;
                if (water > L) water = L;
                if (water < -1e-9) return false;
            }

            while (idx < events.size() && events.get(idx).time == curTime) {
                usage += events.get(idx).delta;
                idx++;
            }
            prevTime = curTime;
        }

        return true;
    }
}
